CREATE TYPE "appeal_status" AS ENUM('open', 'closed');--> statement-breakpoint
CREATE TYPE "appeal_decision" AS ENUM('reopened', 'upheld');--> statement-breakpoint
CREATE TABLE "moderation_appeals" ("id" text PRIMARY KEY NOT NULL, "product_id" text NOT NULL, "seller_id" text NOT NULL, "message" text NOT NULL, "status" "appeal_status" DEFAULT 'open' NOT NULL, "decision" "appeal_decision", "response" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "responded_at" timestamp with time zone, CONSTRAINT "moderation_appeals_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "moderation_appeals_seller_id_sellers_id_fk" FOREIGN KEY ("seller_id") REFERENCES "sellers"("id") ON DELETE NO ACTION ON UPDATE NO ACTION);
